contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient) public {
        bool firstReverted;
        bool secondReverted;
        try c.getFirstWithdrawalBonus(recipient) { firstReverted = false; } catch { firstReverted = true; }
        try c.getFirstWithdrawalBonus(recipient) { secondReverted = false; } catch { secondReverted = true; }
        assert(!firstReverted && secondReverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient) public {
        uint balBefore = address(this).balance;
        bool reverted;
        try c.getFirstWithdrawalBonus(recipient) { reverted = false; } catch { reverted = true; }
        bool locked = c._locked();
        assert(reverted && !locked && address(c).balance == 0 && address(this).balance == balBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient) public {
        require(recipient != address(c));
        uint balBefore = address(recipient).balance;
        bool reverted;
        try c.getFirstWithdrawalBonus(recipient) { reverted = false; } catch { reverted = true; }
        assert(!reverted || (address(recipient).balance == balBefore + 100 && c._locked() == false));
    }
    receive() external payable {}
}
